{"name": "configure_theme_analyst_role_permissions", "query": "
-- ============================================================
-- STEP 2: Grant / Revoke permissions for the theme_analyst role
-- Reference tables: full SELECT (no write access)
-- Main data tables: SELECT only (no INSERT/UPDATE/DELETE)
-- ============================================================

-- ── Reference tables ─────────────────────────────────────────
GRANT USAGE ON SCHEMA public TO theme_analyst;

GRANT SELECT ON public.lego_themes          TO theme_analyst;
GRANT SELECT ON public.lego_colors          TO theme_analyst;
GRANT SELECT ON public.lego_parts           TO theme_analyst;
GRANT SELECT ON public.lego_part_categories TO theme_analyst;

-- ── Main data tables ─────────────────────────────────────────
GRANT SELECT ON public.lego_sets            TO theme_analyst;
GRANT SELECT ON public.lego_inventories     TO theme_analyst;
GRANT SELECT ON public.lego_inventory_parts TO theme_analyst;

-- ── Explicitly revoke write permissions (defence in depth) ────
REVOKE INSERT, UPDATE, DELETE, TRUNCATE
  ON public.lego_themes, public.lego_colors,
     public.lego_parts, public.lego_part_categories,
     public.lego_sets, public.lego_inventories,
     public.lego_inventory_parts
  FROM theme_analyst;

-- ── Allow the role to execute the helper function ─────────────
GRANT EXECUTE ON FUNCTION public.get_user_theme_id() TO theme_analyst;
"}

{"name": "enable_rls_on_lego_tables", "query": "
-- ============================================================
-- STEP 3: Enable Row-Level Security on the main data tables
-- ============================================================
ALTER TABLE public.lego_sets            ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lego_inventories     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lego_inventory_parts ENABLE ROW LEVEL SECURITY;

-- Make RLS bypass available for postgres / superuser roles
-- (RLS is still enforced for theme_analyst since it has no BYPASSRLS)
ALTER TABLE public.lego_sets            FORCE ROW LEVEL SECURITY;
ALTER TABLE public.lego_inventories     FORCE ROW LEVEL SECURITY;
ALTER TABLE public.lego_inventory_parts FORCE ROW LEVEL SECURITY;
"}

